                    expectedDronePos: {{
                        lat: droneLat,
                        lon: droneLon
                    }}
                }};
            }} else {{
                return {{
                    mapFound: false,
                    markerFound: false,
                    markerPosition: null,
                    originalMapCenter: null,
                    newMapCenter: null,
                    mapZoom: null,
                    expectedDronePos: null
                }};
            }}
        """)

        # Check if map was found
        if not map_data["mapFound"]:
            logger.error("❌ Leaflet map instance not found")
